  Local Ltac open_KX := pose proof KX as (RHx & RFx & FXS & XPx & CEx & NSX).

  Abbreviation above_img := (Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) Xc).

  Abbreviation miss A n := (Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) Xc).

  (* [comment removed for export] *)
  Lemma kx_obj : forall O n A cs, aobj LB0 LF O n -> miss A (Z.of_nat (cells_size cs)) -> O <= A -> A + Z.of_nat (cells_size cs) <= O + n ->
    rw_cells asegs m1 A cs -> rw_cells asegs m2 A cs.
  Proof.
    open_KX. intros O n A cs AO M H1 H2 C. eapply (xpres_rw_cells H); [exact XPx| exact C|].
    eapply (xclient_range_aobj H HH); [exact RHx| exact RFx| eapply aobj_sub; [apply ao_up; exact AO| exact H1| exact H2]| lia| exact M| exact FXS].
  Qed.

  Lemma kx_win : forall O bs', aobj LB0 LF O (Z.of_nat (length bs')) -> miss O (Z.of_nat (length bs')) -> bytes_at asegs m1 O bs' -> bytes_at asegs m2 O bs'.
  Proof.
    open_KX. intros O bs' AO M W. eapply (xpres_bytes_at H); [exact XPx| exact W|].
    eapply (xclient_range_aobj H HH); [exact RHx| exact RFx| apply ao_up; exact AO| lia| exact M| exact FXS].
  Qed.

  Lemma kx_acc : forall O n a k, aobj LB0 LF O n -> 0 <= n -> accessible m1 a k -> O <= a -> a + k <= O + n -> accessible m2 a k.
  Proof.
    open_KX. intros O n a k AO Hn AC H1 H2.
    eapply (aobj_xpres_accessible H HH); [exact RHx| exact RFx| apply ao_up; exact AO| exact Hn| exact XPx| exact NSX| exact FXS| exact AC| exact H1| exact H2].
  Qed.

  (* [comment removed for export] *)
  Lemma kx_stack : forall A cs, SP <= A -> miss A (Z.of_nat (cells_size cs)) -> rw_cells asegs m1 A cs -> rw_cells asegs m2 A cs.
  Proof.
    open_KX. intros A cs LE M C. eapply (xpres_rw_cells H); [exact XPx| exact C|]. eapply (xcl_stack H HH X); [exact RFx| exact FXS| exact CEx| exact LE| exact M].
  Qed.

  (* [comment removed for export] *)
  Lemma kx_ffr : forall A cs, ff <= A -> A + Z.of_nat (cells_size cs) <= ff + 128 -> miss A (Z.of_nat (cells_size cs)) ->
    rw_cells asegs m1 A cs -> rw_cells asegs m2 A cs.
  Proof.
    open_KX. intros A cs H1 H2 M C. eapply (xpres_rw_cells H); [exact XPx| exact C|]. eapply (xcl_frame H HH MX CX X XOK); [exact RFx| exact FXS| exact H1| exact H2| lia| exact M].
  Qed.

  Lemma kx_row : forall cs, Z.of_nat (cells_size cs) = 16 -> miss (sh ff) 16 -> rw_cells asegs m1 (sh ff) cs -> rw_cells asegs m2 (sh ff) cs.
  Proof.
    open_KX. intros cs SZ M C. eapply (xpres_rw_cells H); [exact XPx| exact C|]. rewrite SZ. eapply (xcl_row H HH MX CX X XOK); [exact RFx| exact FXS| exact M].
  Qed.

  Lemma kx_flag : miss fp 1 -> rw_cells asegs m1 fp [C1 (b8 1)] -> rw_cells asegs m2 fp [C1 (b8 1)].
  Proof.
    open_KX. intros M C. eapply (xpres_rw_cells H); [exact XPx| exact C|]. cbn [cells_size csize Nat.add]. eapply (xcl_flag H HH MX CX X XOK); [exact RFx| exact FXS| exact M].
  Qed.

  (* [comment removed for export] *)
  Lemma kx_img_forall : above_img -> forall A n, A + n <= AIMG_TOP -> Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (Xc ++ XS').
  Proof.
    open_KX. intros XI A n TOP. apply Forall_app. split.
    - eapply Forall_impl; [| exact XI]. intros [l h] K. cbn [fst snd] in *. left. lia.
    - eapply Forall_impl; [| exact FXS]. intros iv FS. pose proof (scratch_facts H HH _ _ [] iv RFx FS) as (_ & K & _). left. lia.
  Qed.

  Lemma kx_statics : above_img -> AXStatics2 m1 -> AXStatics2 m2.
  Proof.
    open_KX. intros XI ST2. eapply (AXStatics2_xpres H); [exact ST2| exact XPx|].
    eapply Forall_impl; [| exact (kx_img_forall XI 0 AIMG_TOP ltac:(lia))]. intros [l h] K. cbn [fst snd] in *. unfold AIMG_TOP in K. lia.
  Qed.
