  Lemma kx_pft : above_img -> APfTab m1 -> APfTab m2.
  Proof.
    open_KX. intros XI PFT. unfold APfTab in *. eapply (xpres_rw_cells H); [exact XPx| exact PFT|]. cbn [cells_size csize Nat.add].
    apply xclient_range_img; [intros a Ha; unfold aimg_client, APF_TABPTR in *; lia| apply (kx_img_forall XI); unfold APF_TABPTR, AIMG_TOP; lia].
  Qed.

  Lemma kx_fti : above_img -> FTInit m1 -> FTInit m2.
  Proof.
    open_KX. intros XI FI. unfold FTInit in *. eapply (xpres_bytes_at H); [exact XPx| exact FI|]. rewrite FT_TAB_BYTES_length.
    apply xclient_range_img; [intros a Ha; unfold aimg_client, P_A_FT_INIT in *; lia| apply (kx_img_forall XI); unfold P_A_FT_INIT, AIMG_TOP; lia].
  Qed.

