  Lemma kx_sv : forall ptr len, ASvOwn (LBn ++ LB0) m1 ptr len -> (1 <= len -> miss ptr len) -> ASvOwn (LBn ++ LB0) m2 ptr len.
  Proof.
    open_KX. intros ptr len [Z0|(L1 & p & cs & IN & C & AD)] M; [left; exact Z0| right]. split; [exact L1|]. exists p, cs.
    split; [exact IN|]. split.
    - eapply (xpres_rw_cells H); [exact XPx| exact C|]. cbn [cells_size csize]. rewrite Nat.add_0_r, Z2Nat.id by lia. split; [eapply (aclient_range_block H); [exact IN| lia| lia]|].
      apply Forall_app. split; [exact (M L1)| exact (proj1 (scratch_off_blk H HH _ _ _ _ _ _ _ _ _ RHx RFx IN FXS))].
    - eapply (blk_xpres_addressable H HH); [exact RHx| exact RFx| exact IN| exact XPx| exact NSX| exact FXS| exact AD].
  Qed.

  Lemma kx_hdr : forall h, HdrOwnA (LBn ++ LB0) m1 h -> (1 <= hv_ml h -> miss (hv_mp h) (hv_ml h)) -> (1 <= hv_tl h -> miss (hv_tp h) (hv_tl h)) ->
    HdrOwnA (LBn ++ LB0) m2 h.
  Proof. intros h (O1 & O2 & R1 & R2) M1 M2. split; [exact (kx_sv _ _ O1 M1)|]. split; [exact (kx_sv _ _ O2 M2)|]. split; [exact R1| exact R2]. Qed.

