Definition bp_frame4 (m : mem) : Prop :=
  exists j0 j160 j184,
       rw_cells asegs m spa (bp_locals207 H X j0 j160 j184)
    /\ rw_cells asegs m (spa + 216) gap
    /\ rw_cells asegs m (bv_unsigned sp + -104) (bp_saves s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells asegs m fp [C1 (b8 1)].
Definition bp_frameF (m : mem) : Prop :=
  exists ja j48 jb j80 jc j112, rw_cells asegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112) /\ rw_cells asegs m (sh ff) (bp_sh F8b F8b F8b).

Lemma frame_split : forall m p, bp_frame H X m p <-> bp_frame4 m /\ bp_frameF m /\ rw_cells asegs m (spa + 208) [C8 (wz p)].
Proof.
  intros m p. split.
  - intros (j0 & j160 & j184 & ja & j48 & jb & j80 & jc & j112 & LOC & GAP & SAV & FFR & SH & FL).
    apply (proj1 (bp_locals_split H MX CX X XOK m j0 j160 j184 p)) in LOC. destruct LOC as [LOC IN].
    split; [exists j0, j160, j184; repeat (split; [assumption|]); exact FL|]. split; [exists ja, j48, jb, j80, jc, j112; split; assumption| exact IN].
  - intros ((j0 & j160 & j184 & LOC & GAP & SAV & FL) & (ja & j48 & jb & j80 & jc & j112 & FFR & SH) & IN).
    exists j0, j160, j184, ja, j48, jb, j80, jc, j112. split; [apply (proj2 (bp_locals_split H MX CX X XOK m j0 j160 j184 p)); split; assumption|].
    repeat (split; [assumption|]); exact FL.
Qed.

