Lemma kx_frame4 : forall sx LBn mh m1 m2 SP Xc XS', kxc sx LBn mh m1 m2 SP Xc XS' -> SP <= spa ->
  (forall A k, aceil <= A -> (A + k <= spa + 208 \/ spa + 216 <= A) -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) Xc) ->
  Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) Xc ->
