Lemma kx_frameF : forall sx LBn mh m1 m2 SP Xc XS', kxc sx LBn mh m1 m2 SP Xc XS' ->
  (forall A k, ff <= A -> A + k <= ff + 128 -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) Xc) ->
  Forall (fun iv : Z * Z => sh ff + 16 <= fst iv \/ snd iv <= sh ff) Xc ->
  bp_frameF m1 -> bp_frameF m2.
Proof.
  intros sx LBn mh m1 m2 SP Xc XS' KX XFF XSH (ja & j48 & jb & j80 & jc & j112 & FFR & SH). exists ja, j48, jb, j80, jc, j112. split.
  - eapply (kx_ffr _ _ _ _ _ _ _ _ KX); [clear; lia| cbn [cells_size csize Nat.add bp_ffr length]; clear; lia| apply XFF; cbn [cells_size csize Nat.add bp_ffr length]; clear; lia| exact FFR].
  - eapply (kx_row _ _ _ _ _ _ _ _ KX); [reflexivity| exact XSH| exact SH].
Qed.

