Lemma body_off_sub : forall es O n A k, body_off es O n -> O <= A -> A + k <= O + n -> body_off es A k.
Proof. intros es O n A k BO H1 H2 x sz IN. destruct (BO x sz IN); lia. Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition xb (es : list mbe) : list (Z * Z) := ((E, E + 24) :: (P + 168, P + 232) :: mb_elemsW es)%Z.

Lemma xb_facts : forall s LBn m es insz,
  as_RHEAP H s (LBn ++ LB0) m -> AMBuf m (P + 168) es insz -> AMBufOwn (LBn ++ LB0) es ->
     Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) (xb es)
  /\ Forall noshadow (xb es)
  /\ (forall A k, (A + k <= E \/ E + 24 <= A) -> (A + k <= P + 168 \/ P + 232 <= A) -> (forall x sz, In (x, sz) es -> A + k <= x \/ x + 24 + sz <= A) ->
        Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (xb es))
  /\ (forall A k, body_off es A k -> forall x sz, In (x, sz) es -> A + k <= x \/ x + 24 + sz <= A)
  /\ (forall A k, aceil <= A -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (xb es))
  /\ (forall A k, ff <= A -> A + k <= ff + 128 -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (xb es))
  /\ Forall (fun iv : Z * Z => sh ff + 16 <= fst iv \/ snd iv <= sh ff) (xb es)
